1	// JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).
2	
3	export class PatchError extends Error {
4	  constructor(message, index) {
5	    super(message);
6	    this.name = 'PatchError';
7	    this.index = index;
8	  }
9	}
10	
11	const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
12	const INDEX_RE = /^(0|[1-9][0-9]*)$/;
13	
14	export function parsePointer(pointer) {
15	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
16	  if (pointer === '') return [];
17	  if (pointer[0] !== '/' || /~(?![01])/.test(pointer)) throw new SyntaxError('invalid pointer');
18	  return pointer
19	    .slice(1)
20	    .split('/')
21	    .map((token) => token.replace(/~[01]/g, (m) => (m === '~0' ? '~' : '/')));
22	}
23	
24	function isContainer(value) {
25	  return typeof value === 'object' && value !== null;
26	}
27	
28	function setMember(obj, name, value) {
29	  // defineProperty keeps an existing member's place and treats __proto__ as an ordinary name.
30	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
31	}
32	
33	function emptyLike(value) {
34	  return Array.isArray(value) ? new Array(value.length) : {};
35	}
36	
37	// Iterative deep copy: keeps -0 and member order, and survives very deep values.
38	function deepCopy(value) {
39	  if (!isContainer(value)) return value;
40	  const root = emptyLike(value);
41	  const stack = [[value, root]];
42	  while (stack.length > 0) {
43	    const [src, dst] = stack.pop();
44	    const keys = Array.isArray(src) ? src.keys() : Object.keys(src);
45	    for (const key of keys) {
46	      const child = src[key];
47	      if (isContainer(child)) {
48	        const copy = emptyLike(child);
49	        setMember(dst, key, copy);
50	        stack.push([child, copy]);
51	      } else {
52	        setMember(dst, key, child);
53	      }
54	    }
55	  }
56	  return root;
57	}
58	
59	function jsonEqual(a, b) {
60	  if (a === b) return true;
61	  if (!isContainer(a) || !isContainer(b)) return false;
62	  if (Array.isArray(a) !== Array.isArray(b)) return false;
63	  if (Array.isArray(a)) {
64	    return a.length === b.length && a.every((item, i) => jsonEqual(item, b[i]));
65	  }
66	  const keys = Object.keys(a);
67	  if (keys.length !== Object.keys(b).length) return false;
68	  return keys.every((key) => Object.hasOwn(b, key) && jsonEqual(a[key], b[key]));
69	}
70	
71	class Failure {
72	  constructor(reason) {
73	    this.reason = reason;
74	  }
75	}
76	
77	function fail(reason) {
78	  throw new Failure(reason);
79	}
80	
81	// Checks that `token` names a value in `container`; fails with `notFound` or `bad index`.
82	function checkNames(container, token, notFound) {
83	  if (Array.isArray(container)) {
84	    if (token === '-') fail(notFound);
85	    if (!INDEX_RE.test(token)) fail('bad index');
86	    if (Number(token) >= container.length) fail(notFound);
87	  } else if (!isContainer(container) || !Object.hasOwn(container, token)) {
88	    fail(notFound);
89	  }
90	}
91	
92	function follow(doc, tokens, notFound) {
93	  let current = doc;
94	  for (const token of tokens) {
95	    checkNames(current, token, notFound);
96	    current = current[token];
97	  }
98	  return current;
99	}
100	
101	function removeValue(doc, tokens, notFound) {
102	  const parent = follow(doc, tokens.slice(0, -1), notFound);
103	  const last = tokens[tokens.length - 1];
104	  checkNames(parent, last, notFound);
105	  if (Array.isArray(parent)) parent.splice(Number(last), 1);
106	  else delete parent[last];
107	}
108	
109	function replaceValue(doc, tokens, value) {
110	  if (tokens.length === 0) return value;
111	  const parent = follow(doc, tokens.slice(0, -1), 'path not found');
112	  const last = tokens[tokens.length - 1];
113	  checkNames(parent, last, 'path not found');
114	  setMember(parent, last, value);
115	  return doc;
116	}
117	
118	function addValue(doc, tokens, value) {
119	  if (tokens.length === 0) return value;
120	  const parent = follow(doc, tokens.slice(0, -1), 'path not found');
121	  const last = tokens[tokens.length - 1];
122	  if (Array.isArray(parent)) {
123	    if (last === '-') {
124	      parent.push(value);
125	    } else if (!INDEX_RE.test(last)) {
126	      fail('bad index');
127	    } else if (Number(last) > parent.length) {
128	      fail('path not found');
129	    } else {
130	      parent.splice(Number(last), 0, value);
131	    }
132	  } else if (isContainer(parent)) {
133	    setMember(parent, last, value);
134	  } else {
135	    fail('path not found');
136	  }
137	  return doc;
138	}
139	
140	function isProperPrefix(prefix, tokens) {
141	  return prefix.length < tokens.length && prefix.every((token, i) => token === tokens[i]);
142	}
143	
144	function sameTokens(a, b) {
145	  return a.length === b.length && a.every((token, i) => token === b[i]);
146	}
147	
148	function pointerMember(op, name) {
149	  if (!Object.hasOwn(op, name) || typeof op[name] !== 'string') return null;
150	  try {
151	    return parsePointer(op[name]);
152	  } catch {
153	    return null;
154	  }
155	}
156	
157	// Returns the checked form of an operation, or the reason it breaks the form rules.
158	function checkForm(op) {
159	  if (op === null || Array.isArray(op) || typeof op !== 'object') return 'not an object';
160	  const name = Object.hasOwn(op, 'op') ? op.op : undefined;
161	  if (typeof name !== 'string' || !OPS.has(name)) return 'bad op';
162	  const path = pointerMember(op, 'path');
163	  if (path === null) return 'bad path';
164	  let from = null;
165	  if (name === 'move' || name === 'copy') {
166	    from = pointerMember(op, 'from');
167	    if (from === null) return 'bad from';
168	  }
169	  if ((name === 'add' || name === 'replace' || name === 'test') && !Object.hasOwn(op, 'value')) {
170	    return 'missing value';
171	  }
172	  if (name === 'remove' && path.length === 0) return 'cannot remove root';
173	  if (name === 'move' && isProperPrefix(from, path)) return 'cannot move into own child';
174	  return { name, path, from, value: op.value };
175	}
176	
177	function applyOne(doc, { name, path, from, value }) {
178	  switch (name) {
179	    case 'add':
180	      return addValue(doc, path, deepCopy(value));
181	    case 'remove':
182	      removeValue(doc, path, 'path not found');
183	      return doc;
184	    case 'replace':
185	      return replaceValue(doc, path, deepCopy(value));
186	    case 'move': {
187	      const moved = follow(doc, from, 'from not found');
188	      if (sameTokens(from, path)) return doc;
189	      removeValue(doc, from, 'from not found');
190	      return addValue(doc, path, moved);
191	    }
192	    case 'copy':
193	      return addValue(doc, path, deepCopy(follow(doc, from,'from not found')));
194	    case 'test':
195	      if (!jsonEqual(follow(doc, path, 'path not found'), value)) fail('test failed');
196	      return doc;
197	  }
198	}
199	
200	export function applyPatch(doc, patch) {
201	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
202	  const ops = [];
203	  for (let i = 0; i < patch.length; i++) {
204	    const checked = checkForm(patch[i]);
205	    if (typeof checked === 'string') throw new PatchError(`operation ${i}: ${checked}`, i);
206	    ops.push(checked);
207	  }
208	  let result = deepCopy(doc);
209	  for (let i = 0; i < ops.length; i++) {
210	    try {
211	      result = applyOne(result, ops[i]);
212	    } catch (err) {
213	      if (err instanceof Failure) throw new PatchError(`operation ${i}: ${err.reason}`, i);
214	      throw err;
215	    }
216	  }
217	  return result;
218	}
