1	#!/usr/bin/env node
2	// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
3	import fs from 'node:fs';
4	import { applyPatch, PatchError } from './jsonpatch.mjs';
5	
6	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
7	const MAX_BYTES = 1048576;
8	const MAX_DEPTH = 1000;
9	
10	class InputError extends Error {
11	  constructor(name, reason, exitCode) {
12	    super(`${name}: ${reason}`);
13	    this.exitCode = exitCode;
14	  }
15	}
16	
17	function readFile(path) {
18	  let fd;
19	  try {
20	    fd = fs.openSync(path, 'r');
21	  } catch (err) {
22	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw new InputError(path, 'no such file', 1);
23	    let isDir = false;
24	    try {
25	      isDir = fs.statSync(path).isDirectory();
26	    } catch {
27	      // Not a directory we can see; fall through to "cannot read".
28	    }
29	    throw new InputError(path, isDir ? 'is a directory' : 'cannot read', 1);
30	  }
31	  try {
32	    if (fs.fstatSync(fd).isDirectory()) throw new InputError(path, 'is a directory', 1);
33	    const chunks = [];
34	    let total = 0;
35	    const buf = Buffer.alloc(65536);
36	    for (;;) {
37	      const n = fs.readSync(fd, buf, 0, buf.length, null);
38	      if (n === 0) break;
39	      total += n;
40	      if (total > MAX_BYTES) throw new InputError(path, 'too large', 1);
41	      chunks.push(Buffer.from(buf.subarray(0, n)));
42	    }
43	    return Buffer.concat(chunks);
44	  } catch (err) {
45	    if (err instanceof InputError) throw err;
46	    throw new InputError(path, err.code === 'EISDIR' ? 'is a directory' : 'cannot read', 1);
47	  } finally {
48	    fs.closeSync(fd);
49	  }
50	}
51	
52	function readStdin() {
53	  return new Promise((resolve, reject) => {
54	    const chunks = [];
55	    let total = 0;
56	    let settled = false;
57	    const stop = (err) => {
58	      if (settled) return;
59	      settled = true;
60	      process.stdin.destroy();
61	      reject(err);
62	    };
63	    process.stdin.on('data', (chunk) => {
64	      if (settled) return;
65	      total += chunk.length;
66	      if (total > MAX_BYTES) stop(new InputError('stdin', 'too large', 1));
67	      else chunks.push(chunk);
68	    });
69	    process.stdin.on('error', () => stop(new InputError('stdin', 'cannot read', 1)));
70	    process.stdin.on('end', () => {
71	      if (settled) return;
72	      settled = true;
73	      resolve(Buffer.concat(chunks));
74	    });
75	  });
76	}
77	
78	// Maximum nesting of arrays and objects in text that JSON.parse has accepted.
79	function jsonDepth(text) {
80	  let depth = 0;
81	  let max = 0;
82	  let inString = false;
83	  for (let i = 0; i < text.length; i++) {
84	    const c = text[i];
85	    if (inString) {
86	      if (c === '\\') i++;
87	      else if (c === '"') inString = false;
88	    } else if (c === '"') {
89	      inString = true;
90	    } else if (c === '[' || c === '{') {
91	      depth++;
92	      if (depth > max) max = depth;
93	    } else if (c === ']' || c === '}') {
94	      depth--;
95	    }
96	  }
97	  return max;
98	}
99	
100	async function loadInput(arg) {
101	  const name = arg === '-' ? 'stdin' : arg;
102	  const bytes = arg === '-' ? await readStdin() : readFile(arg);
103	  let text;
104	  try {
105	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
106	  } catch {
107	    throw new InputError(name, 'invalid UTF-8', 3);
108	  }
109	  let value;
110	  try {
111	    value = JSON.parse(text);
112	  } catch {
113	    throw new InputError(name, 'invalid JSON', 3);
114	  }
115	  if (jsonDepth(text) > MAX_DEPTH) throw new InputError(name, 'too deep', 3);
116	  return value;
117	}
118	
119	async function main(args) {
120	  if (args.length < 1 || args.length > 2) return fail(USAGE, 2);
121	  const [patchArg, docArg = '-'] = args;
122	  if (patchArg === '-' && docArg === '-') return fail(USAGE, 2);
123	  let result;
124	  try {
125	    const patch = await loadInput(patchArg);
126	    const doc = await loadInput(docArg);
127	    result = applyPatch(doc, patch);
128	  } catch (err) {
129	    if (err instanceof InputError) return fail(`Error: ${err.message}`, err.exitCode);
130	    if (err instanceof PatchError) return fail(`Error: ${err.message}`, 4);
131	    throw err;
132	  }
133	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
134	  process.exitCode = 0;
135	}
136	
137	function fail(line, code) {
138	  process.stderr.write(`${line}\n`);
139	  process.exitCode = code;
140	}
141	
142	await main(process.argv.slice(2));
